//! Procedural macros that parse Rust source into a `syn` syntax tree,
//! inspect/transform it, and emit new tokens with `quote`.

use proc_macro::TokenStream;
use quote::quote;
use syn::visit_mut::{self, VisitMut};
use syn::{parse_macro_input, Expr, ItemFn, LitStr};

/// Example attribute macro: wraps every integer literal in the function body
/// with `checked(...)`-style instrumentation is overkill for a template, so
/// this one simply logs the function name on entry and rewrites `+` into
/// `wrapping_add` calls to demonstrate a tree transformation.
#[proc_macro_attribute]
pub fn trace(attr: TokenStream, item: TokenStream) -> TokenStream {
    let label = if attr.is_empty() {
        None
    } else {
        Some(parse_macro_input!(attr as LitStr))
    };
    let mut func = parse_macro_input!(item as ItemFn);

    // Transform: rewrite `a + b` into `a.wrapping_add(b)`.
    WrappingAdd.visit_block_mut(&mut func.block);

    // Inspect: read the function's name from the syntax tree.
    let name = label
        .map(|l| l.value())
        .unwrap_or_else(|| func.sig.ident.to_string());
    let body = &func.block;
    func.block = syn::parse_quote!({
        ::std::eprintln!("enter {}", #name);
        #body
    });

    quote!(#func).into()
}

struct WrappingAdd;

impl VisitMut for WrappingAdd {
    fn visit_expr_mut(&mut self, expr: &mut Expr) {
        // Recurse first so nested additions are rewritten bottom-up.
        visit_mut::visit_expr_mut(self, expr);
        if let Expr::Binary(bin) = expr
            && matches!(bin.op, syn::BinOp::Add(_))
        {
            let (lhs, rhs) = (&bin.left, &bin.right);
            *expr = syn::parse_quote!((#lhs).wrapping_add(#rhs));
        }
    }
}
EOF
mkdir -p tests && cat > tests/trace.rs <<'EOF'
use macros::trace;

#[trace]
fn add(a: u8, b: u8) -> u8 {
    a + b
}

#[trace("custom label")]
fn add3(a: u8, b: u8, c: u8) -> u8 {
    a + b + c
}

#[test]
fn rewrites_addition_to_wrapping() {
    assert_eq!(add(250, 10), 4);
    assert_eq!(add3(200, 50, 10), 4);
}
EOF
cargo test 2>&1 | tail -25

